    27	    public static void main(String[] args) {
    28	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
    29	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
    30	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
    31	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    32	
    33	        PGSimpleDataSource dataSource = new PGSimpleDataSource();
    34	        dataSource.setUrl(dbUrl);
    35	        dataSource.setUser(dbUser);
    36	        dataSource.setPassword(dbPassword);
    37	
    38	        Database database = new Database(dataSource);
    39	
    40	        RoomRepository roomRepository = new PostgresRoomRepository(database);
    41	        ReservationRepository reservationRepository = new PostgresReservationRepository(database);
    42	        MessageRepository messageRepository = new PostgresMessageRepository(database);
    43	
    44	        List<ReservationEventListener> listeners = List.of(
    45	            new GuestNotifier(messageRepository),
    46	            new HousekeepingNotifier(messageRepository),
    47	            new FinanceNotifier(messageRepository)
    48	        );
    49	
    50	        ReservationService reservationService = new ReservationService(
    51	            roomRepository,
    52	            reservationRepository,
    53	            listeners
    54	        );
    55	
    56	        ReportService reportService = new ReportService(roomRepository, reservationRepository);
    57	
    58	        ApiHandler apiHandler = new ApiHandler(
    59	            roomRepository,
    60	            reservationService,
    61	            reportService,
    62	            messageRepository
    63	        );
    64	
    65	        ObjectMapper objectMapper = new ObjectMapper()
    66	            .registerModule(new JavaTimeModule())
    67	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    68	
    69	        Javalin app = Javalin.create(config -> {
    70	            config.jsonMapper(new JavalinJackson(objectMapper, true));
    71	        });
    72	
    73	        app.get("/rooms", apiHandler::getRooms);
    74	        app.post("/reservations", apiHandler::createReservation);
    75	        app.get("/reservations/{id}", apiHandler::getReservation);
    76	        app.post("/reservations/{id}/confirmation", apiHandler::confirmReservation);
    77	        app.post("/reservations/{id}/cancellation", apiHandler::cancelReservation);
    78	        app.post("/reservations/{id}/check-in", apiHandler::checkIn);
    79	        app.post("/reservations/{id}/check-out", apiHandler::checkOut);
    80	        app.get("/reservations/{id}/document", apiHandler::getDocument);
    81	        app.get("/messages", apiHandler::getMessages);
    82	        app.get("/reports/occupancy", apiHandler::getOccupancyReport);
    83	        app.get("/reports/revenue", apiHandler::getRevenueReport);
    84	
    85	        app.start(port);
    86	
    87	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
    88	        System.out.println("Servidor iniciado na porta " + port);
    89	    }
    90	}

