  1	package br.com.pousadamarealta.api;
  2	
  3	import br.com.pousadamarealta.api.dto.*;
  4	import br.com.pousadamarealta.domain.RatePlan;
  5	import br.com.pousadamarealta.domain.Reservation;
  6	import br.com.pousadamarealta.domain.ReservationStatus;
  7	import br.com.pousadamarealta.repository.MessageRepository;
  8	import br.com.pousadamarealta.repository.RoomRepository;
  9	import br.com.pousadamarealta.service.*;
 10	import io.javalin.http.Context;
 11	import io.javalin.http.HttpStatus;
 12	
 13	import java.time.LocalDate;
 14	import java.time.YearMonth;
 15	import java.time.format.DateTimeParseException;
 16	import java.util.stream.Collectors;
 17	
 18	public final class ApiHandler {
 19	    private final RoomRepository roomRepository;
 20	    private final ReservationService reservationService;
 21	    private final ReportService reportService;
 22	    private final MessageRepository messageRepository;
 23	
 24	    public ApiHandler(RoomRepository roomRepository,
 25	                     ReservationService reservationService,
 26	                     ReportService reportService,
 27	                     MessageRepository messageRepository) {
 28	        this.roomRepository = roomRepository;
 29	        this.reservationService = reservationService;
 30	        this.reportService = reportService;
 31	        this.messageRepository = messageRepository;
 32	    }
 33	
 34	    public void getRooms(Context ctx) {
 35	        var rooms = roomRepository.findAll().stream()
 36	            .map(RoomDto::from)
 37	            .collect(Collectors.toList());
 38	        ctx.json(rooms);
 39	    }
 40	
 41	    public void createReservation(Context ctx) {
 42	        try {
 43	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 44	
 45	            if (request.checkOut().isBefore(request.checkIn()) ||
 46	                request.checkOut().equals(request.checkIn())) {
 47	                ctx.status(HttpStatus.BAD_REQUEST)
 48	                   .json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
 49	                return;
 50	            }
 51	
 52	            if (request.guests() < 1) {
 53	                ctx.status(HttpStatus.BAD_REQUEST)
 54	                   .json(new ErrorResponse("INVALID_REQUEST", "At least one guest is required"));
 55	                return;
 56	            }
 57	
 58	            RatePlan ratePlan;
 59	            try {
 60	                ratePlan = RatePlan.valueOf(request.ratePlan());
 61	            } catch (IllegalArgumentException e) {
 62	                ctx.status(HttpStatus.BAD_REQUEST)
 63	                   .json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
 64	                return;
 65	            }
 66	
 67	            Reservation reservation = reservationService.createReservation(
 68	                request.roomNumber(),
 69	                request.guestName(),
 70	                request.guestEmail(),
 71	                request.guestCpf(),
 72	                request.checkIn(),
 73	                request.checkOut(),
 74	                request.guests(),
 75	                ratePlan
 76	            );
 77	
 78	            ctx.status(HttpStatus.CREATED).json(ReservationDto.from(reservation));
 79	
 80	        } catch (RoomNotFoundException e) {
 81	            ctx.status(HttpStatus.NOT_FOUND)
 82	               .json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
 83	        } catch (RoomUnavailableException e) {
 84	            ctx.status(HttpStatus.CONFLICT)
 85	               .json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
 86	        } catch (IllegalArgumentException e) {
 87	            if (e.getMessage().contains("capacity")) {
 88	                ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
 89	                   .json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
 90	            } else {
 91	                ctx.status(HttpStatus.BAD_REQUEST)
 92	                   .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 93	            }
 94	        } catch (Exception e) {
 95	            ctx.status(HttpStatus.BAD_REQUEST)
 96	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
 97	        }
 98	    }
 99	
100	    public void getReservation(Context ctx) {
101	        try {
102	            Long id = Long.parseLong(ctx.pathParam("id"));
103	            Reservation reservation = reservationService.getReservation(id);
104	            ctx.json(ReservationDto.from(reservation));
105	        } catch (NumberFormatException e) {
106	            ctx.status(HttpStatus.BAD_REQUEST)
107	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
108	        } catch (ReservationNotFoundException e) {
109	            ctx.status(HttpStatus.NOT_FOUND)
110	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
111	        }
112	    }
113	
114	    public void confirmReservation(Context ctx) {
115	        try {
116	            Long id = Long.parseLong(ctx.pathParam("id"));
117	            Reservation reservation = reservationService.confirmReservation(id);
118	            ctx.json(ReservationDto.from(reservation));
119	        } catch (NumberFormatException e) {
120	            ctx.status(HttpStatus.BAD_REQUEST)
121	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
122	        } catch (ReservationNotFoundException e) {
123	            ctx.status(HttpStatus.NOT_FOUND)
124	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
125	        } catch (IllegalStateException e) {
126	            ctx.status(HttpStatus.CONFLICT)
127	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
128	        }
129	    }
130	
131	    public void cancelReservation(Context ctx) {
132	        try {
133	            Long id = Long.parseLong(ctx.pathParam("id"));
134	            Reservation reservation = reservationService.cancelReservation(id);
135	            ctx.json(ReservationDto.from(reservation));
136	        } catch (NumberFormatException e) {
137	            ctx.status(HttpStatus.BAD_REQUEST)
138	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
139	        } catch (ReservationNotFoundException e) {
140	            ctx.status(HttpStatus.NOT_FOUND)
141	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
142	        } catch (IllegalStateException e) {
143	            ctx.status(HttpStatus.CONFLICT)
144	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
145	        }
146	    }
147	
148	    public void checkIn(Context ctx) {
149	        try {
150	            Long id = Long.parseLong(ctx.pathParam("id"));
151	            Reservation reservation = reservationService.checkIn(id);
152	            ctx.json(ReservationDto.from(reservation));
153	        } catch (NumberFormatException e) {
154	            ctx.status(HttpStatus.BAD_REQUEST)
155	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
156	        } catch (ReservationNotFoundException e) {
157	            ctx.status(HttpStatus.NOT_FOUND)
158	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
159	        } catch (IllegalStateException e) {
160	            ctx.status(HttpStatus.CONFLICT)
161	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
162	        }
163	    }
164	
165	    public void checkOut(Context ctx) {
166	        try {
167	            Long id = Long.parseLong(ctx.pathParam("id"));
168	            Reservation reservation = reservationService.checkOut(id);
169	            ctx.json(DocumentDto.from(reservation));
170	        } catch (NumberFormatException e) {
171	            ctx.status(HttpStatus.BAD_REQUEST)
172	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
173	        } catch (ReservationNotFoundException e) {
174	            ctx.status(HttpStatus.NOT_FOUND)
175	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
176	        } catch (IllegalStateException e) {
177	            ctx.status(HttpStatus.CONFLICT)
178	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
179	        }
180	    }
181	
182	    public void getDocument(Context ctx) {
183	        try {
184	            Long id = Long.parseLong(ctx.pathParam("id"));
185	            Reservation reservation = reservationService.getReservation(id);
186	
187	            if (reservation.status() == ReservationStatus.PENDING ||
188	                reservation.status() == ReservationStatus.CANCELLED) {
189	                ctx.status(HttpStatus.CONFLICT)
190	                   .json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
191	                return;
192	            }
193	
194	            ctx.json(DocumentDto.from(reservation));
195	        } catch (NumberFormatException e) {
196	            ctx.status(HttpStatus.BAD_REQUEST)
197	               .json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
198	        } catch (ReservationNotFoundException e) {
199	            ctx.status(HttpStatus.NOT_FOUND)
200	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
201	        }
202	    }
203	
204	    public void getMessages(Context ctx) {
205	        var messages = messageRepository.findAll().stream()
206	            .map(MessageDto::from)
207	            .collect(Collectors.toList());
208	        ctx.json(messages);
209	    }
210	
211	    public void getOccupancyReport(Context ctx) {
212	        try {
213	            String dateStr = ctx.queryParam("date");
214	            if (dateStr == null || dateStr.isEmpty()) {
215	                ctx.status(HttpStatus.BAD_REQUEST)
216	                   .json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
217	                return;
218	            }
219	
220	            LocalDate date = LocalDate.parse(dateStr);
221	            String csv = reportService.generateOccupancyReport(date);
222	            ctx.contentType("text/csv; charset=utf-8").result(csv);
223	
224	        } catch (DateTimeParseException e) {
225	            ctx.status(HttpStatus.BAD_REQUEST)
