  1	package br.com.pousadamarealta.domain;
  2	
  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import java.time.temporal.ChronoUnit;
  6	
  7	public final class Reservation {
  8	    private final Long id;
  9	    private final String roomNumber;
 10	    private final RoomType roomType;
 11	    private final int roomCapacity;
 12	    private final BigDecimal roomNightlyRate;
 13	    private final String guestName;
 14	    private final String guestEmail;
 15	    private final String guestCpf;
 16	    private final LocalDate checkIn;
 17	    private final LocalDate checkOut;
 18	    private final int guests;
 19	    private final RatePlan ratePlan;
 20	    private final int nights;
 21	    private final BigDecimal subtotal;
 22	    private final BigDecimal discount;
 23	    private final BigDecimal total;
 24	    private ReservationStatus status;
 25	    private BigDecimal amountPaid;
 26	    private BigDecimal refund;
 27	
 28	    public Reservation(Long id, Room room, String guestName, String guestEmail, String guestCpf,
 29	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 30	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 31	            throw new IllegalArgumentException("Check-out must be after check-in");
 32	        }
 33	        if (guests < 1) {
 34	            throw new IllegalArgumentException("At least one guest is required");
 35	        }
 36	        if (guests > room.capacity()) {
 37	            throw new IllegalArgumentException("Guests exceed room capacity");
 38	        }
 39	
 40	        this.id = id;
 41	        this.roomNumber = room.number();
 42	        this.roomType = room.type();
 43	        this.roomCapacity = room.capacity();
 44	        this.roomNightlyRate = room.nightlyRate();
 45	        this.guestName = guestName;
 46	        this.guestEmail = guestEmail;
 47	        this.guestCpf = guestCpf;
 48	        this.checkIn = checkIn;
 49	        this.checkOut = checkOut;
 50	        this.guests = guests;
 51	        this.ratePlan = ratePlan;
 52	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 53	        this.subtotal = PriceCalculator.calculateSubtotal(checkIn, checkOut, room.nightlyRate());
 54	        this.discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
 55	        this.total = PriceCalculator.calculateTotal(subtotal, discount);
 56	        this.status = ReservationStatus.PENDING;
 57	        this.amountPaid = BigDecimal.ZERO;
 58	        this.refund = null;
 59	    }
 60	
 61	    public Reservation(Long id, String roomNumber, RoomType roomType, int roomCapacity, BigDecimal roomNightlyRate,
 62	                       String guestName, String guestEmail, String guestCpf, LocalDate checkIn, LocalDate checkOut,
 63	                       int guests, RatePlan ratePlan, int nights, BigDecimal subtotal, BigDecimal discount,
 64	                       BigDecimal total, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
 65	        this.id = id;
 66	        this.roomNumber = roomNumber;
 67	        this.roomType = roomType;
 68	        this.roomCapacity = roomCapacity;
 69	        this.roomNightlyRate = roomNightlyRate;
 70	        this.guestName = guestName;
 71	        this.guestEmail = guestEmail;
 72	        this.guestCpf = guestCpf;
 73	        this.checkIn = checkIn;
 74	        this.checkOut = checkOut;
 75	        this.guests = guests;
 76	        this.ratePlan = ratePlan;
 77	        this.nights = nights;
 78	        this.subtotal = subtotal;
 79	        this.discount = discount;
 80	        this.total = total;
 81	        this.status = status;
 82	        this.amountPaid = amountPaid;
 83	        this.refund = refund;
 84	    }
 85	
 86	    public void confirm() {
 87	        if (status != ReservationStatus.PENDING) {
 88	            throw new IllegalStateException("Only pending reservations can be confirmed");
 89	        }
 90	        this.status = ReservationStatus.CONFIRMED;
 91	        this.amountPaid = this.total;
 92	    }
 93	
 94	    public void performCheckIn() {
 95	        if (status != ReservationStatus.CONFIRMED) {
 96	            throw new IllegalStateException("Only confirmed reservations can be checked in");
 97	        }
 98	        this.status = ReservationStatus.CHECKED_IN;
 99	    }
100	
101	    public void performCheckOut() {
102	        if (status != ReservationStatus.CHECKED_IN) {
103	            throw new IllegalStateException("Only checked-in reservations can be checked out");
104	        }
105	        this.status = ReservationStatus.CHECKED_OUT;
106	    }
107	
108	    public void cancel() {
109	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
110	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
111	        }
112	
113	        BigDecimal refundAmount = BigDecimal.ZERO;
114	        if (status == ReservationStatus.CONFIRMED && ratePlan == RatePlan.STANDARD) {
115	            refundAmount = amountPaid;
116	        }
117	
118	        this.status = ReservationStatus.CANCELLED;
119	        this.refund = refundAmount;
120	    }
121	
122	    public boolean occupiesNight(LocalDate night) {
123	        return (night.equals(checkIn) || night.isAfter(checkIn)) && night.isBefore(checkOut);
124	    }
