 28	    public Reservation(Long id, Room room, String guestName, String guestEmail, String guestCpf,
 29	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 30	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
