153	public final class PriceCalculator {
154	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
155	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
156	
157	    public static BigDecimal calculateNightPrice(LocalDate date, BigDecimal baseRate) {
158	        BigDecimal rate = baseRate;
159	        if (isHighSeason(date)) {
160	            rate = rate.multiply(HIGH_SEASON_MULTIPLIER);
161	        }
162	        return rate.setScale(2, ROUNDING);
163	    }
164	
165	    public static BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut, BigDecimal baseRate) {
166	        BigDecimal subtotal = BigDecimal.ZERO;
167	        LocalDate date = checkIn;
168	        while (date.isBefore(checkOut)) {
169	            subtotal = subtotal.add(calculateNightPrice(date, baseRate));
170	            date = date.plusDays(1);
171	        }
172	        return subtotal.setScale(2, ROUNDING);
173	    }
174	
175	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
176	        BigDecimal discount = subtotal.multiply(ratePlan.discountRate());
177	        return discount.setScale(2, ROUNDING);
178	    }
179	
180	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
181	        return subtotal.subtract(discount).setScale(2, ROUNDING);
182	    }
183	
184	    private static boolean isHighSeason(LocalDate date) {
185	        Month month = date.getMonth();
186	        int day = date.getDayOfMonth();
187	
188	        if (month == Month.DECEMBER && day >= 15) {
189	            return true;
190	        }
191	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
192	            return true;
193	        }
194	        if (month == Month.JULY) {
195	            return true;
196	        }
197	        return false;
198	    }
