178	public final class PostgresReservationRepository implements ReservationRepository {
179	    private final Database database;
180	
181	    public PostgresReservationRepository(Database database) {
182	        this.database = database;
183	    }
184	
185	    @Override
186	    public Reservation save(Reservation reservation) {
187	        if (reservation.id() == null) {
188	            return insert(reservation);
189	        } else {
190	            return update(reservation);
191	        }
192	    }
193	
194	    private Reservation insert(Reservation reservation) {
195	        String sql = """
196	            INSERT INTO reservations (
197	                room_number, room_type, room_capacity, room_nightly_rate,
198	                guest_name, guest_email, guest_cpf,
199	                check_in, check_out, guests, rate_plan,
200	                nights, subtotal, discount, total,
201	                status, amount_paid, refund
202	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
203	            RETURNING id
204	            """;
205	
206	        try (Connection conn = database.getConnection();
207	             PreparedStatement stmt = conn.prepareStatement(sql)) {
208	
209	            setReservationParameters(stmt, reservation);
210	
211	            try (ResultSet rs = stmt.executeQuery()) {
212	                if (rs.next()) {
213	                    long id = rs.getLong("id");
214	                    return new Reservation(
215	                        id,
216	                        reservation.roomNumber(),
217	                        reservation.roomType(),
218	                        reservation.roomCapacity(),
219	                        reservation.roomNightlyRate(),
220	                        reservation.guestName(),
221	                        reservation.guestEmail(),
222	                        reservation.guestCpf(),
223	                        reservation.checkIn(),
224	                        reservation.checkOut(),
225	                        reservation.guests(),
226	                        reservation.ratePlan(),
227	                        reservation.nights(),
228	                        reservation.subtotal(),
229	                        reservation.discount(),
230	                        reservation.total(),
231	                        reservation.status(),
232	                        reservation.amountPaid(),
233	                        reservation.refund()
234	                    );
235	                }
236	            }
237	        } catch (SQLException e) {
238	            throw new RuntimeException("Failed to insert reservation", e);
239	        }
240	
241	        throw new RuntimeException("Failed to get generated ID");
242	    }
243	
244	    private Reservation update(Reservation reservation) {
245	        String sql = """
246	            UPDATE reservations SET
247	                room_number = ?, room_type = ?, room_capacity = ?, room_nightly_rate = ?,
248	                guest_name = ?, guest_email = ?, guest_cpf = ?,
249	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
250	                nights = ?, subtotal = ?, discount = ?, total = ?,
251	                status = ?, amount_paid = ?, refund = ?
252	            WHERE id = ?
253	            """;
254	
255	        try (Connection conn = database.getConnection();
256	             PreparedStatement stmt = conn.prepareStatement(sql)) {
257	
258	            setReservationParameters(stmt, reservation);
259	            stmt.setLong(19, reservation.id());
260	
261	            stmt.executeUpdate();
262	            return reservation;
263	
264	        } catch (SQLException e) {
265	            throw new RuntimeException("Failed to update reservation", e);
266	        }
267	    }
268	
269	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
270	        stmt.setString(1, reservation.roomNumber());
271	        stmt.setString(2, reservation.roomType().name());
272	        stmt.setInt(3, reservation.roomCapacity());
273	        stmt.setBigDecimal(4, reservation.roomNightlyRate());
274	        stmt.setString(5, reservation.guestName());
275	        stmt.setString(6, reservation.guestEmail());
276	        stmt.setString(7, reservation.guestCpf());
277	        stmt.setDate(8, Date.valueOf(reservation.checkIn()));
278	        stmt.setDate(9, Date.valueOf(reservation.checkOut()));
279	        stmt.setInt(10, reservation.guests());
280	        stmt.setString(11, reservation.ratePlan().name());
281	        stmt.setInt(12, reservation.nights());
282	        stmt.setBigDecimal(13, reservation.subtotal());
283	        stmt.setBigDecimal(14, reservation.discount());
284	        stmt.setBigDecimal(15, reservation.total());
285	        stmt.setString(16, reservation.status().name());
286	        stmt.setBigDecimal(17, reservation.amountPaid());
287	        if (reservation.refund() != null) {
288	            stmt.setBigDecimal(18, reservation.refund());
289	        } else {
290	            stmt.setNull(18, Types.DECIMAL);
291	        }
292	    }
293	
294	    @Override
295	    public Optional<Reservation> findById(Long id) {
296	        String sql = "SELECT * FROM reservations WHERE id = ?";
297	
298	        try (Connection conn = database.getConnection();
299	             PreparedStatement stmt = conn.prepareStatement(sql)) {
300	
301	            stmt.setLong(1, id);
302	
303	            try (ResultSet rs = stmt.executeQuery()) {
304	                if (rs.next()) {
305	                    return Optional.of(mapReservation(rs));
306	                }
307	            }
308	        } catch (SQLException e) {
309	            throw new RuntimeException("Failed to find reservation by id", e);
310	        }
311	
312	        return Optional.empty();
313	    }
314	
315	    @Override
316	    public List<Reservation> findByRoomAndNight(String roomNumber, LocalDate night, ReservationStatus... excludeStatuses) {
317	        String sql = """
318	            SELECT * FROM reservations
319	            WHERE room_number = ?
320	            AND check_in <= ?
321	            AND check_out > ?
322	            """;
323	
324	        if (excludeStatuses.length > 0) {
325	            String placeholders = Arrays.stream(excludeStatuses)
326	                .map(s -> "?")
327	                .collect(Collectors.joining(", "));
328	            sql += " AND status NOT IN (" + placeholders + ")";
329	        }
330	
331	        List<Reservation> reservations = new ArrayList<>();
332	
333	        try (Connection conn = database.getConnection();
334	             PreparedStatement stmt = conn.prepareStatement(sql)) {
335	
336	            stmt.setString(1, roomNumber);
337	            stmt.setDate(2, Date.valueOf(night));
338	            stmt.setDate(3, Date.valueOf(night));
339	
340	            for (int i = 0; i < excludeStatuses.length; i++) {
341	                stmt.setString(4 + i, excludeStatuses[i].name());
342	            }
343	
344	            try (ResultSet rs = stmt.executeQuery()) {
345	                while (rs.next()) {
346	                    reservations.add(mapReservation(rs));
347	                }
348	            }
349	        } catch (SQLException e) {
350	            throw new RuntimeException("Failed to find reservations by room and night", e);
351	        }
352	
353	        return reservations;
354	    }
355	
356	    @Override
357	    public List<Reservation> findByNight(LocalDate night) {
358	        String sql = """
359	            SELECT * FROM reservations
360	            WHERE check_in <= ?
361	            AND check_out > ?
362	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
363	            ORDER BY room_number
364	            """;
365	
366	        List<Reservation> reservations = new ArrayList<>();
367	
368	        try (Connection conn = database.getConnection();
369	             PreparedStatement stmt = conn.prepareStatement(sql)) {
370	
371	            stmt.setDate(1, Date.valueOf(night));
372	            stmt.setDate(2, Date.valueOf(night));
373	
374	            try (ResultSet rs = stmt.executeQuery()) {
375	                while (rs.next()) {
376	                    reservations.add(mapReservation(rs));
377	                }
378	            }
379	        } catch (SQLException e) {
380	            throw new RuntimeException("Failed to find reservations by night", e);
381	        }
382	
383	        return reservations;
384	    }
385	
386	    @Override
387	    public List<Reservation> findByCheckInMonth(YearMonth month) {
388	        String sql = """
389	            SELECT * FROM reservations
390	            WHERE EXTRACT(YEAR FROM check_in) = ?
391	            AND EXTRACT(MONTH FROM check_in) = ?
392	            ORDER BY check_in, id
393	            """;
394	
395	        List<Reservation> reservations = new ArrayList<>();
396	
397	        try (Connection conn = database.getConnection();
398	             PreparedStatement stmt = conn.prepareStatement(sql)) {
399	
400	            stmt.setInt(1, month.getYear());
401	            stmt.setInt(2, month.getMonthValue());
402	
403	            try (ResultSet rs = stmt.executeQuery()) {
404	                while (rs.next()) {
405	                    reservations.add(mapReservation(rs));
406	                }
407	            }
408	        } catch (SQLException e) {
409	            throw new RuntimeException("Failed to find reservations by check-in month", e);
410	        }
411	
412	        return reservations;
413	    }
414	
415	    private Reservation mapReservation(ResultSet rs) throws SQLException {
416	        return new Reservation(
417	            rs.getLong("id"),
418	            rs.getString("room_number"),
419	            RoomType.valueOf(rs.getString("room_type")),
420	            rs.getInt("room_capacity"),
421	            rs.getBigDecimal("room_nightly_rate"),
422	            rs.getString("guest_name"),
423	            rs.getString("guest_email"),
424	            rs.getString("guest_cpf"),
425	            rs.getDate("check_in").toLocalDate(),
426	            rs.getDate("check_out").toLocalDate(),
427	            rs.getInt("guests"),
428	            RatePlan.valueOf(rs.getString("rate_plan")),
429	            rs.getInt("nights"),
430	            rs.getBigDecimal("subtotal"),
431	            rs.getBigDecimal("discount"),
432	            rs.getBigDecimal("total"),
433	            ReservationStatus.valueOf(rs.getString("status")),
434	            rs.getBigDecimal("amount_paid"),
435	            rs.getBigDecimal("refund")
436	        );
437	    }
438	}
