 25	    public String generateOccupancyReport(LocalDate date) {
 26	        List<Reservation> reservations = reservationRepository.findByNight(date);
 27	        List<Room> allRooms = roomRepository.findAll();
 28	
 29	        StringBuilder csv = new StringBuilder();
 30	        csv.append("room,type,reservation,check_in,check_out\n");
 31	
 32	        for (Reservation reservation : reservations) {
 33	            csv.append(String.format("%s,%s,%d,%s,%s\n",
 34	                reservation.roomNumber(),
 35	                reservation.roomType().name(),
 36	                reservation.id(),
 37	                reservation.checkIn().format(DATE_FORMAT),
 38	                reservation.checkOut().format(DATE_FORMAT)
 39	            ));
 40	        }
 41	
 42	        csv.append(String.format("total,%d/%d\n", reservations.size(), allRooms.size()));
 43	
 44	        return csv.toString();
 45	    }
 46	
 47	    public String generateRevenueReport(YearMonth month) {
 48	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
 49	
 50	        StringBuilder csv = new StringBuilder();
 51	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 52	
 53	        BigDecimal total = BigDecimal.ZERO;
 54	
 55	        for (Reservation reservation : reservations) {
 56	            BigDecimal revenue = reservation.amountPaid().subtract(
 57	                reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO
 58	            );
 59	
 60	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
 61	                csv.append(String.format("%d,%s,%s,%s,%s,%.2f\n",
 62	                    reservation.id(),
 63	                    reservation.roomNumber(),
 64	                    reservation.checkIn().format(DATE_FORMAT),
 65	                    reservation.checkOut().format(DATE_FORMAT),
 66	                    reservation.status().name(),
 67	                    revenue
 68	                ));
 69	                total = total.add(revenue);
 70	            }
